import time
import hashlib
from datetime import datetime
from enum import Enum
from typing import Literal, List, Dict, Any, Optional, Set, Callable, Type
from pydantic import BaseModel, Field, ConfigDict, field_validator, ValidationError
import uuid

# 1. Trusted Execution Context
class ExecutionContext(BaseModel):
    """Application-provided trusted state. Not generated by the model."""
    actor_id: str
    tenant_id: str
    roles: Set[str]
    environment: Literal["dev", "staging", "production"] = "production"
    request_id: str

# 2. Typed Errors and Retry Classification
class ErrorCode(str, Enum):
    INVALID_ARGUMENT = "INVALID_ARGUMENT"
    NOT_FOUND = "NOT_FOUND"
    PERMISSION_DENIED = "PERMISSION_DENIED"
    CONFLICT = "CONFLICT"
    RATE_LIMITED = "RATE_LIMITED"
    TIMEOUT = "TIMEOUT"
    UNAVAILABLE = "UNAVAILABLE"
    POISONED_RESULT = "POISONED_RESULT"
    INTERNAL_TOOL_ERROR = "INTERNAL_TOOL_ERROR"
    UNKNOWN_TOOL = "UNKNOWN_TOOL"

class ToolError(Exception):
    def __init__(self, code: ErrorCode, safe_message: str, retryable: bool = False):
        super().__init__(safe_message)
        self.code = code
        self.safe_message = safe_message
        self.retryable = retryable

class RetryPolicy(BaseModel):
    max_attempts: int = 3
    base_delay: float = 1.0
    max_delay: float = 10.0
    retryable_codes: Set[ErrorCode] = Field(default_factory=lambda: {ErrorCode.TIMEOUT, ErrorCode.RATE_LIMITED, ErrorCode.UNAVAILABLE})

# 3. Provenance and Results
class Evidence(BaseModel):
    """Wrapper for facts originating from tools."""
    source_id: str
    source_type: str
    observed_at: datetime
    tenant_id: str
    payload: Any
    # Removed freshness_seconds and max_freshness_seconds to separate policy from observation

class ValidatedEvidence(BaseModel):
    """Evidence that has passed the validation pipeline."""
    evidence: Evidence
    content_trust: Literal["TRUSTED", "UNTRUSTED", "QUARANTINED"] = "TRUSTED"
    contains_instruction_injection: bool = False
    validation_notes: List[str] = Field(default_factory=list)

class ValidationFailure(BaseModel):
    evidence: Evidence
    reason: str

# 4. Tool Registry and Cataloging
class ToolEffect(str, Enum):
    READ = "READ"
    PROPOSE = "PROPOSE"
    WRITE = "WRITE"

class ToolDefinition(BaseModel):
    name: str
    purpose: str
    input_model: type[BaseModel]
    result_model: type[BaseModel]
    effect: ToolEffect
    required_permissions: Set[str]
    timeout: float = 10.0
    retry_policy: RetryPolicy = Field(default_factory=RetryPolicy)
    cost_class: Literal["low", "medium", "high"] = "low"
    version: str = "v1"
    max_result_age_seconds: int = 300  # Policy extracted from observation

# 5. Domain Models (Northstar Scenario)
class ServiceEnum(str, Enum):
    checkout = "checkout"
    payments = "payments"
    catalog = "catalog"

class RegionEnum(str, Enum):
    eu_west = "eu-west"
    us_east = "us-east"

class ServiceHealthRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    service: ServiceEnum

class ServiceHealthResult(BaseModel):
    status: Literal["healthy", "degraded", "down"]
    latency_ms: int

class QueryLogsRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    service: ServiceEnum
    region: RegionEnum
    minutes: int = Field(ge=1, le=240)

class LogEvidenceResult(BaseModel):
    error_count: int
    sample_codes: List[str]

class DeploymentRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    service: ServiceEnum

class DeploymentResult(BaseModel):
    version: str
    deployed_at: datetime
    status: str

class TicketSearchRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    region: RegionEnum
    query: Optional[str] = None

class TicketSearchResult(BaseModel):
    ticket_ids: List[str]
    open_count: int

class IncidentDraftRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    incident_id: str
    evidence_ids: List[str]
    summary: str

class IncidentDraftResult(BaseModel):
    draft_id: str
    status: str

# 6. Approvals for Restart
class RestartProposal(BaseModel):
    model_config = ConfigDict(extra="forbid")
    service: ServiceEnum
    region: RegionEnum

# We make the restart proposing tool return the proposal directly (or wrapped in a receipt)
class RestartProposalReceipt(BaseModel):
    proposal_id: str
    proposal: RestartProposal
    status: Literal["pending_approval"]
    digest: str

class RestartReceipt(BaseModel):
    receipt_id: str
    service: str
    status: str
    restarted_at: datetime

class RestartApprovalPayload(BaseModel):
    proposal: RestartProposal
    tenant_id: str
    target: str
    evidence_ids: List[str]
    policy_version: str

class Approval(BaseModel):
    decision: Literal["approve", "reject"]
    approver_id: str
    approval_digest: str
    expires_at: float

class RestartCommand(BaseModel):
    proposal: RestartProposal
    approval: Approval
    idempotency_key: str


# Simulated backend registry of restart receipts (Moved from Notebook for deterministic testing)
restart_receipts = {}

def execute_restart(command: RestartCommand) -> RestartReceipt:
    """
    The authoritative backend executor.
    Only accepts validated internal RestartCommand objects produced after digest-bound approval checks.
    """
    if command.idempotency_key in restart_receipts:
        # Return existing receipt on idempotent retry
        return restart_receipts[command.idempotency_key]
        
    receipt = RestartReceipt(
        receipt_id=f"rcpt-{uuid.uuid4().hex[:8]}",
        service=command.proposal.service.value,
        status="restarting",
        restarted_at=datetime.now()
    )
    restart_receipts[command.idempotency_key] = receipt
    return receipt

def compute_approval_digest(payload: RestartApprovalPayload) -> str:
    return hashlib.sha256(payload.model_dump_json(exclude_unset=True).encode("utf-8")).hexdigest()

def compute_proposal_digest(proposal: BaseModel) -> str:
    return hashlib.sha256(proposal.model_dump_json(exclude_unset=True).encode("utf-8")).hexdigest()

ALLOWED_RESTART_APPROVERS = {"manager-01", "system-admin"}

def validate_restart_approval(
    proposal: RestartProposal, 
    approval: Approval, 
    ctx: ExecutionContext,
    evidence_ids: List[str],
    policy_version: str = "1.0"
) -> RestartCommand:
    if approval.decision != "approve":
        raise ToolError(ErrorCode.PERMISSION_DENIED, "Approval decision is not 'approve'")
    if approval.approver_id not in ALLOWED_RESTART_APPROVERS:
        raise ToolError(ErrorCode.PERMISSION_DENIED, f"Approver {approval.approver_id} is not authorized for production restarts.")
    
    if time.time() > approval.expires_at:
        raise ToolError(ErrorCode.PERMISSION_DENIED, "Approval has expired.")

    expected_target = f"{proposal.service.value}-{proposal.region.value}"
    
    # Reconstruct the payload that should have been signed
    expected_payload = RestartApprovalPayload(
        proposal=proposal,
        tenant_id=ctx.tenant_id,
        target=expected_target,
        evidence_ids=evidence_ids,
        policy_version=policy_version
    )
    
    expected_digest = compute_approval_digest(expected_payload)
    if approval.approval_digest != expected_digest:
        raise ToolError(ErrorCode.PERMISSION_DENIED, "Digest mismatch: The approval payload has been mutated or tampered with.")
         
    return RestartCommand(
        proposal=proposal,
        approval=approval,
        idempotency_key=f"idemp-{approval.approval_digest}-{ctx.request_id}"
    )

